import type {SidebarsConfig} from '@docusaurus/plugin-content-docs';

// A league entry: a clickable category whose link is the generated landing page
// (docs/docs/{prefix}/index.md) and whose children are the auto-generated
// reference subtree (reference/{api}.md + loaders.md). The reference pages are
// regenerated from endpoint metadata by `python tools/codegen/generate.py --docs`
// and ordered/labelled via the generated _category_.json + page frontmatter, so
// new endpoints surface in the nav with no sidebar edit. Only adding a whole new
// LEAGUE needs a line here.
function league(prefix: string, label: string) {
  return {
    type: 'category' as const,
    label,
    link: {type: 'doc' as const, id: `${prefix}/index`},
    items: [{type: 'autogenerated' as const, dirName: `${prefix}/reference`}],
  };
}

const sidebars: SidebarsConfig = {
  // Single curated sidebar grouped by sport family (basketball / football / baseball /
  // hockey) so cross-league helpers cluster with the leagues that consume them.
  // Within each family pro leagues come first, then NCAA. The opening sections
  // (Architecture + Parsers + Parameter reference) cover package-wide patterns;
  // the executed-notebook Tutorials sit at the very bottom, below the per-sport
  // API-doc sections.
  docs: [
    {type: 'doc', id: 'intro', label: 'Getting Started'},
    {type: 'doc', id: 'ecosystem', label: 'Ecosystem & philosophy'},
    {type: 'doc', id: 'quality-of-life', label: 'Quality-of-life helpers'},
    {type: 'doc', id: 'architecture/espn-cross-league', label: 'How it works'},
    {type: 'doc', id: 'parsers/index', label: 'Parser layer'},
    {type: 'doc', id: 'reference/parameters', label: 'Parameter reference'},
    {type: 'doc', id: 'reference/python-helpers', label: 'Package helpers'},
    {
      type: 'category',
      label: 'Basketball',
      items: [
        league('nba', 'NBA'),
        league('wnba', 'WNBA'),
        league('mbb', 'MBB'),
        league('wbb', 'WBB'),
      ],
    },
    {
      type: 'category',
      label: 'Football',
      items: [
        league('nfl', 'NFL'),
        league('cfb', 'CFB'),
      ],
    },
    {
      type: 'category',
      label: 'Baseball',
      items: [league('mlb', 'MLB')],
    },
    {
      type: 'category',
      label: 'Hockey',
      items: [
        league('nhl', 'NHL'),
        league('pwhl', 'PWHL'),
      ],
    },
    // Cross-sport betting markets (The Odds API). Not tied to a single sport,
    // so it gets its own top-level section rather than nesting under one.
    {
      type: 'category',
      label: 'Betting',
      items: [league('odds', 'Odds')],
    },
    // Executed example notebooks, rendered to docs/docs/tutorials/ by
    // `python tools/codegen/render_notebooks.py` (refreshed weekly in
    // live-tests-cron). The whole section sits at the bottom, below the per-sport
    // API-doc sections; pages order by their frontmatter sidebar_position
    // (Quickstart first, then one per sport).
    {
      type: 'category',
      label: 'Tutorials',
      link: {
        type: 'generated-index',
        title: 'Tutorials',
        description:
          'Executed example notebooks rendered as pages — a cross-sport Quickstart ' +
          'plus one per sport (NBA, WNBA, MBB, WBB, NFL, CFB, MLB, NHL, PWHL). ' +
          'Refreshed weekly against the live APIs; source notebooks live in ' +
          'examples/notebooks/.',
      },
      items: [{type: 'autogenerated', dirName: 'tutorials'}],
    },
  ],
};

export default sidebars;
